{
  "command": "git show fb6cc92 --stat && git show fb6cc92",
  "description": "Show the commit that turned birth-cloud dust off"
}

{
  "command": "grep -rn \"birth_cloud_dust\" --include=*.py --include=*.json --include=*.ipynb --include=*.md --include=*.html . | grep -v \"^./data/\" | head -50",
  "description": "Find other places that set the birth-cloud dust default"
}

{
  "command": "grep -rn \"birth_cloud_dust\" --include='*.py' --include='*.json' --include='*.ipynb' --include='*.md' --include='*.html' . | grep -v \"^./data/\" | cut -c1-250 | head -60",
  "description": "Find other places that set the birth-cloud dust default"
}

{
  "command": "sed -i '' 's/\"    \\\\\"birth_cloud_dust\\\\\": False,  # True: power-law/\"    \\\\\"birth_cloud_dust\\\\\": True,  # True: power-law/' notebooks/ceridwen_integrated_photometry_spectra.ipynb && git diff && grep -n '<span class=\"model-s\">Birth-cloud dust' wiki/notes/model.md | cut -c1-200",
  "description": "Set birth-cloud dust default back to True and show diff"
}

{
  "command": "git -C ceridwen status --short | head; python3 -m pytest -q tests/test_ceridwen_dr2_production.py tests/test_dust_bump.py 2>&1 | tail -5",
  "description": "Check submodule state and run the related tests",
  "timeout": 300000
}

{
  "command": "ls -d .venv venv 2>/dev/null; for p in .venv/bin/python venv/bin/python; do [ -x \"$p\" ] && $p -m pytest -q tests/test_ceridwen_dr2_production.py tests/test_dust_bump.py 2>&1 | tail -5; done",
  "description": "Run related tests with the project virtualenv",
  "timeout": 300000
}

{
  "command": ".venv/bin/python -m pytest -q tests/test_ceridwen_dr2_production.py 2>&1 | tail -3",
  "description": "Run the production-settings tests",
  "timeout": 300000
}

{
  "command": "git stash -q && .venv/bin/python -m pytest -q tests/test_ceridwen_dr2_production.py 2>&1 | tail -1; git stash pop -q && git diff --stat; .venv/bin/python -m pytest -q tests/test_ceridwen_dr2_production.py 2>&1 | grep -E \"^E \" | sort | uniq -c | head -5",
  "description": "Compare test failures with and without the change",
  "timeout": 300000
}

{
  "command": "git add notebooks/ceridwen_integrated_photometry_spectra.ipynb && git commit -q -m \"Birth-cloud dust on by default\n\nCo-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>\" && git log --oneline -1 && git push 2>&1 | tail -3",
  "description": "Commit the default change and push"
}
